SELECT id AS seatId, concert_id AS concertId, section,
       seat_sequence AS seatSequence, seat_label AS seatLabel, grade, price, status
FROM seat
WHERE concert_id = #{concertId}
AND section = #{section}
AND grade = #{grade}
AND status = #{status}
ORDER BY section ASC, seat_sequence ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM seat
WHERE concert_id = #{concertId}
AND section = #{section}
AND grade = #{grade}
AND status = #{status}

SELECT MAX(seat_sequence)
FROM seat
WHERE concert_id = #{concertId} AND section = #{section}
